// Code generated by tgo. DO NOT EDIT.

// Package tgoruntime supports generated tgo validation.
package tgoruntime

import (
	"fmt"
	"reflect"
)

// Identity identifies one reference value during reconstruction.
type Identity struct {
	Type     reflect.Type
	Kind     reflect.Kind
	Pointer  uintptr
	Length   int
	Capacity int
}

// Context preserves aliases and stops recursion in one validation call.
type Context struct {
	seen map[Identity]reflect.Value
}

// NewContext starts one reconstruction graph.
func NewContext() *Context {
	return &Context{seen: make(map[Identity]reflect.Value)}
}

// Reconstructor is implemented by generated tgo model types.
type Reconstructor interface {
	TgoReconstruct(*Context) (any, error)
}

// RebuildAs copies one typed value and reconstructs nested tgo models.
func RebuildAs[T any](value T, context *Context) (T, error) {
	rebuilt, err := Rebuild(reflect.ValueOf(value), context)
	if err != nil {
		var zero T
		return zero, err
	}
	var result T
	if rebuilt.IsValid() {
		reflect.ValueOf(&result).Elem().Set(rebuilt)
	}
	return result, nil
}

// Rebuild copies one supported Go value and reconstructs nested tgo models.
func Rebuild(value reflect.Value, context *Context) (reflect.Value, error) {
	if !value.IsValid() {
		return value, nil
	}
	switch value.Kind() {
	case reflect.Pointer:
		return rebuildPointer(value, context)
	case reflect.Slice:
		return rebuildSlice(value, context)
	case reflect.Map:
		return rebuildMap(value, context)
	case reflect.Interface:
		return rebuildInterface(value, context)
	}
	if value.CanInterface() {
		if model, ok := value.Interface().(Reconstructor); ok {
			rebuilt, err := model.TgoReconstruct(context)
			if err != nil {
				return reflect.Value{}, err
			}
			return reflect.ValueOf(rebuilt), nil
		}
	}
	return rebuildValue(value, context)
}

func rebuildValue(value reflect.Value, context *Context) (reflect.Value, error) {
	switch value.Kind() {
	case reflect.Array:
		return rebuildArray(value, context)
	case reflect.Struct:
		return rebuildStruct(value, context)
	case reflect.Chan:
		if ContainsModel(value.Type(), make(map[reflect.Type]bool)) {
			return reflect.Value{}, fmt.Errorf("cannot validate channel %s", value.Type())
		}
	case reflect.Func:
		if ContainsModel(value.Type(), make(map[reflect.Type]bool)) {
			return reflect.Value{}, fmt.Errorf("cannot validate function %s", value.Type())
		}
	case reflect.UnsafePointer:
		return reflect.Value{}, fmt.Errorf("cannot validate unsafe pointer %s", value.Type())
	}
	return value, nil
}

func rebuildPointer(value reflect.Value, context *Context) (reflect.Value, error) {
	if value.IsNil() {
		return reflect.Zero(value.Type()), nil
	}
	key := identity(value)
	if rebuilt, ok := context.seen[key]; ok {
		return rebuilt, nil
	}
	rebuilt := reflect.New(value.Type().Elem())
	context.seen[key] = rebuilt
	element, err := Rebuild(value.Elem(), context)
	if err != nil {
		return reflect.Value{}, err
	}
	rebuilt.Elem().Set(element)
	return rebuilt, nil
}

func rebuildSlice(value reflect.Value, context *Context) (reflect.Value, error) {
	if value.IsNil() {
		return reflect.Zero(value.Type()), nil
	}
	key := identity(value)
	if rebuilt, ok := context.seen[key]; ok {
		return rebuilt, nil
	}
	rebuilt := reflect.MakeSlice(value.Type(), value.Len(), value.Len())
	context.seen[key] = rebuilt
	for index := 0; index < value.Len(); index++ {
		element, err := Rebuild(value.Index(index), context)
		if err != nil {
			return reflect.Value{}, err
		}
		rebuilt.Index(index).Set(element)
	}
	return rebuilt, nil
}

func rebuildMap(value reflect.Value, context *Context) (reflect.Value, error) {
	if value.IsNil() {
		return reflect.Zero(value.Type()), nil
	}
	key := identity(value)
	if rebuilt, ok := context.seen[key]; ok {
		return rebuilt, nil
	}
	rebuilt := reflect.MakeMapWithSize(value.Type(), value.Len())
	context.seen[key] = rebuilt
	iterator := value.MapRange()
	for iterator.Next() {
		mapKey, err := Rebuild(iterator.Key(), context)
		if err != nil {
			return reflect.Value{}, err
		}
		mapValue, err := Rebuild(iterator.Value(), context)
		if err != nil {
			return reflect.Value{}, err
		}
		rebuilt.SetMapIndex(mapKey, mapValue)
	}
	return rebuilt, nil
}

func rebuildInterface(value reflect.Value, context *Context) (reflect.Value, error) {
	if value.IsNil() {
		return reflect.Zero(value.Type()), nil
	}
	element, err := Rebuild(value.Elem(), context)
	if err != nil {
		return reflect.Value{}, err
	}
	rebuilt := reflect.New(value.Type()).Elem()
	rebuilt.Set(element)
	return rebuilt, nil
}

func rebuildArray(value reflect.Value, context *Context) (reflect.Value, error) {
	rebuilt := reflect.New(value.Type()).Elem()
	for index := 0; index < value.Len(); index++ {
		element, err := Rebuild(value.Index(index), context)
		if err != nil {
			return reflect.Value{}, err
		}
		rebuilt.Index(index).Set(element)
	}
	return rebuilt, nil
}

func rebuildStruct(value reflect.Value, context *Context) (reflect.Value, error) {
	rebuilt := reflect.New(value.Type()).Elem()
	rebuilt.Set(value)
	for index := 0; index < value.NumField(); index++ {
		fieldType := value.Type().Field(index)
		if !fieldType.IsExported() {
			return reflect.Value{}, fmt.Errorf(
				"cannot validate private field %s.%s",
				value.Type(), fieldType.Name,
			)
		}
		field, err := Rebuild(value.Field(index), context)
		if err != nil {
			return reflect.Value{}, err
		}
		rebuilt.Field(index).Set(field)
	}
	return rebuilt, nil
}

func identity(value reflect.Value) Identity {
	result := Identity{Type: value.Type(), Kind: value.Kind(), Pointer: value.Pointer()}
	if value.Kind() == reflect.Slice {
		result.Length = value.Len()
		result.Capacity = value.Cap()
	}
	return result
}

// ContainsModel reports whether a type can contain a generated tgo model.
func ContainsModel(typ reflect.Type, seen map[reflect.Type]bool) bool {
	if typ == nil || seen[typ] {
		return false
	}
	seen[typ] = true
	reconstructor := reflect.TypeOf((*Reconstructor)(nil)).Elem()
	if typ.Implements(reconstructor) ||
		(typ.Kind() != reflect.Pointer && reflect.PointerTo(typ).Implements(reconstructor)) {
		return true
	}
	switch typ.Kind() {
	case reflect.Interface:
		return true
	case reflect.Pointer, reflect.Slice, reflect.Array, reflect.Chan:
		return ContainsModel(typ.Elem(), seen)
	case reflect.Map:
		return ContainsModel(typ.Key(), seen) || ContainsModel(typ.Elem(), seen)
	case reflect.Func:
		return functionContainsModel(typ, seen)
	case reflect.Struct:
		return structContainsModel(typ, seen)
	}
	return false
}

func functionContainsModel(typ reflect.Type, seen map[reflect.Type]bool) bool {
	for index := 0; index < typ.NumIn(); index++ {
		if ContainsModel(typ.In(index), seen) {
			return true
		}
	}
	for index := 0; index < typ.NumOut(); index++ {
		if ContainsModel(typ.Out(index), seen) {
			return true
		}
	}
	return false
}

func structContainsModel(typ reflect.Type, seen map[reflect.Type]bool) bool {
	for index := 0; index < typ.NumField(); index++ {
		if ContainsModel(typ.Field(index).Type, seen) {
			return true
		}
	}
	return false
}
